// ورودی: همان آیتم‌هایی که قبلاً به Supabase (compare.commission) فرستاده می‌شد
// هر آیتم {company_key, rate} یا یک آیتم با آرایه‌ی rows / body / data
const SITE = 'site1';
const list = [];
for (const it of $input.all()) {
  const j = it.json;
  const arr = Array.isArray(j) ? j : Array.isArray(j.rows) ? j.rows : Array.isArray(j.body) ? j.body : Array.isArray(j.data) ? j.data : [j];
  list.push(...arr);
}
const seen = new Set(), rows = [];
for (const r of list) {
  if (!r || !r.company_key) continue;
  if (r.coverage && r.coverage !== 'third') continue;
  if (seen.has(r.company_key)) continue;
  seen.add(r.company_key);
  rows.push({ company_key: String(r.company_key), rate: r.rate == null || r.rate === '' ? null : Number(r.rate) });
}
// اگر اسکرپ چیزی برنگرداند، فایل قبلی دست نمی‌خورد
if (!rows.length) return [];
rows.sort((a, b) => (b.rate ?? -1) - (a.rate ?? -1) || a.company_key.localeCompare(b.company_key));
const doc = { site: SITE, coverage: 'third', captured_at: new Date().toISOString(), rows };
return [{ json: {
  path: 'data/' + SITE + '.json',
  count: rows.length,
  content: Buffer.from(JSON.stringify(doc, null, 1) + '\n').toString('base64')
} }];

